// Fork backport of vercel/ai GHSA-866g-f22w-33x8 response body limits.
// Keep the provider-utils 2.2.8 synchronous parsing API unchanged.
const FORK_MAX_RESPONSE_BYTES = 8 * 1024 * 1024;
async function forkReadResponseBodyAsText(response) {
  const tooLarge = () => new RangeError(`Response body exceeds fork limit of ${FORK_MAX_RESPONSE_BYTES} bytes`);
  const length = response.headers.get("content-length");
  if (length !== null && /^\d+$/.test(length.trim()) && Number(length) > FORK_MAX_RESPONSE_BYTES) {
    try { await response.body?.cancel(); } catch { /* preserve the size error */ }
    throw tooLarge();
  }
  if (response.body === null) return "";
  const reader = response.body.getReader();
  const chunks = [];
  let totalBytes = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!(value instanceof Uint8Array)) throw new TypeError("Response stream must contain bytes");
      totalBytes += value.byteLength;
      if (totalBytes > FORK_MAX_RESPONSE_BYTES) throw tooLarge();
      chunks.push(value);
    }
  } finally {
    try { await reader.cancel(); } catch { /* preserve read/abort errors */ }
    reader.releaseLock();
  }
  const bytes = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  return new TextDecoder().decode(bytes);
}

